typedef unsigned int uint32_t;
typedef unsigned short uint16_t;
typedef unsigned char uint8_t;
typedef unsigned long size_t;
void memcpy(void*, const void*, size_t);
void* malloc(size_t);

typedef struct { uint16_t sensor_id; uint16_t num_readings; uint8_t data[256]; } sensor_packet_t;
typedef struct { float value; uint32_t timestamp; } sensor_reading_t;

void sensor_parse_readings(const sensor_packet_t* pkt, sensor_reading_t* out, size_t out_cap)
{
  void* buf = (void*)malloc(pkt->num_readings * sizeof(sensor_reading_t));
  memcpy(buf, pkt->data, pkt->num_readings * sizeof(sensor_reading_t));
  memcpy(out, buf, pkt->num_readings * sizeof(sensor_reading_t));
}

uint16_t sensor_get_id(const sensor_packet_t* pkt)
{
  return pkt->sensor_id;
}
